// UNIVERSE PROVIDER
//
// Supported universes:
//   - NASDAQ/NYSE: broad listed U.S. equity universe
//   - S&P 500: S&P 500 constituents
//   - Russell 2000: Russell 2000 constituents
//
// The scanner does not query option chains. It recommends strikes from
// the underlying price and requires the user to verify the actual contract.

import { UniverseProvider, unavailable } from './interfaces.js';

const NASDAQ_LISTED_URL =
  'https://www.nasdaqtrader.com/dynamic/SymDir/nasdaqlisted.txt';

const OTHER_LISTED_URL =
  'https://www.nasdaqtrader.com/dynamic/SymDir/otherlisted.txt';

// These are maintained as external universe sources.
// We intentionally do not hard-code constituent lists into the Worker.
const SP500_URL =
  'https://www.spglobal.com/spdji/en/indices/equity/sp-500/';

const RUSSELL_URL =
  'https://www.lseg.com/en/ftse-russell/';

function parsePipeDelimited(text, symbolCol, testIssueCol) {
  const lines = text.trim().split('\n');
  const out = [];

  for (let i = 1; i < lines.length - 1; i++) {
    const cols = lines[i].split('|');
    const symbol = cols[symbolCol];
    const isTest = cols[testIssueCol] === 'Y';

    if (
      symbol &&
      !isTest &&
      /^[A-Z.]{1,6}$/.test(symbol)
    ) {
      out.push(symbol.replace('.', '-'));
    }
  }

  return out;
}

async function fetchListedUniverse() {
  let nasdaqText;
  let otherText;

  try {
    const [a, b] = await Promise.all([
      fetch(NASDAQ_LISTED_URL),
      fetch(OTHER_LISTED_URL),
    ]);

    if (!a.ok || !b.ok) {
      return unavailable(
        `Symbol directory fetch failed (${a.status}/${b.status})`,
      );
    }

    [nasdaqText, otherText] = await Promise.all([
      a.text(),
      b.text(),
    ]);
  } catch (err) {
    return unavailable(
      `Symbol directory network error: ${err.message}`,
    );
  }

  const nasdaq = parsePipeDelimited(
    nasdaqText,
    0,
    3,
  );

  const other = parsePipeDelimited(
    otherText,
    0,
    6,
  );

  const universe = Array.from(
    new Set([...nasdaq, ...other]),
  ).sort();

  if (universe.length === 0) {
    return unavailable(
      'Symbol directories parsed to zero symbols',
    );
  }

  return universe;
}

export class NasdaqTraderUniverseProvider extends UniverseProvider {
  async getUniverse(_env) {
    const universe = await fetchListedUniverse();

    if (!Array.isArray(universe)) {
      return universe;
    }

    return {
      ok: true,
      data: universe,
      sourceTimestamp: Date.now(),
      retrievedTimestamp: Date.now(),
      freshness: 'delayed',
      universes: {
        'NASDAQ/NYSE': universe,
        'S&P 500': [],
        'Russell 2000': [],
      },
      universeSources: {
        'NASDAQ/NYSE': 'Nasdaq Trader symbol directories',
        'S&P 500': SP500_URL,
        'Russell 2000': RUSSELL_URL,
      },
      note:
        'S&P 500 and Russell 2000 membership sources are registered for the universe layer; constituent ingestion will be added separately so membership is not fabricated or hard-coded.',
    };
  }
}
